import React, { useState, useEffect, useRef } from 'react'
import FeatureSection from './DocFeaturesList/FeatureSection'

export default function DocFeaturesList({features}) {
  const [visibleCount, setVisibleCount] = useState(6);
  const loadMoreRef = useRef();

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && visibleCount < features.length) {
          setVisibleCount(prev => Math.min(prev + 3, features.length));
        }
      },
      { 
        threshold: 0.1,
        rootMargin: '50px' // Trigger 50px before reaching the element
      }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => observer.disconnect();
  }, [visibleCount, features.length]);

  const handleLoadMore = () => {
    setVisibleCount(prev => Math.min(prev + 6, features.length));
  };

  const visibleFeatures = features.slice(0, visibleCount);
  const hasMore = visibleCount < features.length;

    return (
        <section className="features-list">
      {visibleFeatures.map((f) => (
            <FeatureSection
              key={f.id}
              id={f.id}
              title={f.sectionNav}
              description={f.sectionDesc}
              importMsg={f.importMsg}
              demo={f.demo}
              code={f.code}
            />
          ))}
      
      {hasMore && (
        <div ref={loadMoreRef} className="load-more-container">
          <button 
            onClick={handleLoadMore}
            className="load-more-btn"
          >
            Load More ({features.length - visibleCount} remaining)
          </button>
        </div>
      )}
        </section>
    )
}
